template:
{%- macro action(a, label, class) -%}
{%- if a.method in ("POST", "PUT", "PATCH", "DELETE") -%}
<button type="button" class="{{ class }}" hx-{{ a.method|lower }}="{{ in_mount(a.href) }}" hx-ext="scrud-json" hx-swap="none" data-scrud-json="fixed" data-scrud-body='{{ a.body|tojson }}' data-scrud-etag="{{ a.etag or '' }}">{{ label }}</button>
{%- endif -%}
{%- endmacro -%}
{%- set actions = value.actions or {} -%}
{%- set promote = actions.promote[0] if actions.promote else none -%}
{%- set changed = value.changed|length -%}
{%- set conflicts = value.conflicts|length -%}
<div class="studio-status" data-studio-status data-studio-endpoints='{{ value.endpoints|tojson }}'>
<ol class="studio-chain" aria-label="Chain">
{%- for branch in value.chain %}<li class="studio-chain-branch{% if branch.published %} studio-chain-published{% endif %}">{{ branch.name }}</li>{% endfor -%}
</ol>
<span class="studio-count" data-studio-changed="{{ changed }}">{{ changed }} changed</span>
<span class="studio-count{% if conflicts %} studio-count-conflicts{% endif %}" data-studio-conflict-count="{{ conflicts }}">{{ conflicts }} conflict{{ "" if conflicts == 1 else "s" }}</span>
<span class="studio-actions">
{%- if actions.pull %}{{ action(actions.pull, "Pull", "studio-pull") }}{% endif -%}
{%- if promote and promote.apply %}{{ action(promote.apply, "Push to " ~ promote.target, "studio-push") }}{% endif -%}
{%- if promote and promote.propose %}{{ action(promote.propose, "Propose to " ~ promote.target, "studio-propose") }}{% endif -%}
</span>
{%- if value.browse_url %}
<a class="studio-browse" href="{{ value.browse_url }}">Browse app on this branch</a>
{%- endif %}
</div>
